K, W, C = 'Knowledge', 'Wisdom', 'Command'
S, R = 'stated', 'reflection'
def ins(t, b, text): return {'type': t, 'basis': b, 'text': text}
def keeps(t): return {'dir': 'keeps', 'text': t}
def loses(t): return {'dir': 'loses', 'text': t}
def between(t): return {'dir': 'between', 'text': t}
AGREE = between("Hebrew, Greek, Latin and King James agree in substance; only the rendering of the divine name and small turns of phrase differ.")
FORMULA = [between("The Latin, Greek and King James all have the speech formula; the divine name is rendered 'the Lord' outside the Hebrew.")]
EXTREM = [loses("Hebrew 'right thumb' and 'right big toe' are lost."), keeps("Greek 'the extremity of his right hand, and the extremity of his right foot'."), between("The Latin and King James have 'thumb' and 'great toe'.")]
LOG = [loses("Hebrew 'log' of oil is lost as a unit name."), keeps("Greek 'kotyle'."), between("The Latin has 'sextarius'; the King James 'log'.")]
WAVE = [loses("Hebrew 'wave them as a wave offering' is lost."), keeps("Greek 'separate it as a separated portion' or 'place as a presentation'."), between("The Latin has 'lift up' or 'offer'; the King James 'wave them for a wave offering'.")]
PALM = [loses("Hebrew 'palm' is lost."), keeps("Greek 'hand'."), between("The Latin and King James have 'hand'.")]
SCARLET = [keeps("Greek 'spun scarlet thread'."), between("The Latin has 'scarlet' and 'sparrows' for the birds; the King James 'scarlet'.")]
P = ['high-priest']

def v(received, explain, shared, k, w, lost, entries=None, cmd=None):
    inst = [ins(K, S, k)]
    if cmd: inst.append(ins(C, S, cmd))
    inst.append(ins(W, R, w))
    return {'received': received, 'explain': explain, 'shared': shared, 'instructions': inst, 'entries': entries if entries is not None else P, 'lost': lost}

